resource "typesense_collection" "orders_eventual" {
name = "orders_eventual"
fields {
name = "order_pk"
type = "string"
}
fields {
name = "user_pk"
type = "string"
reference = "${typesense_collection.users.name}.user_pk"
async_reference = true
}
}
