import typesense
import os
import time
import json

client = typesense.Client({
    'nodes': [{
        'host': 'localhost',
        'port': '8108',
        'protocol': 'http'
    }],
    'api_key': os.getenv('TYPESENSE_API_KEY', 'xyz'),
    'connection_timeout_seconds': 5
})

# Clean up collections if they exist
for coll in ['likes', 'products', 'users']:
    try:
        client.collections[coll].delete()
        print(f"Deleted collection: {coll}")
    except Exception as e:
        print(f"Collection {coll} did not exist or could not be deleted: {e}")

# Define schemas
users_schema = {
    'name': 'users',
    'fields': [
        {'name': 'username', 'type': 'string'}
    ]
}

products_schema = {
    'name': 'products',
    'fields': [
        {'name': 'product_name', 'type': 'string'}
    ]
}

likes_schema = {
    'name': 'likes',
    'fields': [
        {
            'name': 'user_id',
            'type': 'string',
            'reference': 'users.id',
            'async_reference': True
        },
        {
            'name': 'product_id',
            'type': 'string',
            'reference': 'products.id',
            'async_reference': True
        }
    ]
}

print("Creating collections...")
client.collections.create(users_schema)
client.collections.create(products_schema)
client.collections.create(likes_schema)
print("Collections created successfully.")

# Index a like BEFORE user and product exist
print("Indexing like document before user and product exist...")
like_doc = {
    'id': 'like-1',
    'user_id': 'user-1',
    'product_id': 'prod-1'
}
res = client.collections['likes'].documents.create(like_doc)
print("Created like doc:", res)

# Let's search likes right now to see if we get any errors or if it shows unresolved references
search_params = {
    'q': '*',
    'include_fields': '$users(*), $products(*)'
}
try:
    search_res = client.collections['likes'].documents.search(search_params)
    print("Search likes (unresolved):", json.dumps(search_res, indent=2))
except Exception as e:
    print("Search likes error:", e)

# Now index the user and product
print("Indexing user and product...")
user_doc = {
    'id': 'user-1',
    'username': 'alice'
}
client.collections['users'].documents.create(user_doc)

product_doc = {
    'id': 'prod-1',
    'product_name': 'laptop'
}
client.collections['products'].documents.create(product_doc)

print("Waiting for references to resolve...")
time.sleep(2)

# Search again
try:
    search_res = client.collections['likes'].documents.search(search_params)
    print("Search likes (resolved):", json.dumps(search_res, indent=2))
except Exception as e:
    print("Search likes error:", e)

